// FilmCam36 / Kodamax / R1 / 2026-10-20
// Contract: opaque SDR photo, sRGB working surface.
// Coordinates and u_resolution use source-image pixels.
// u_time is a saved integer photo seed [0,4095], not a clock.
uniform shader u_image;
uniform float2 u_resolution;
uniform float u_time;

float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
float shortSide() { return max(min(u_resolution.x, u_resolution.y), 1.0); }
float3 readPhoto(float2 p) {
    return u_image.eval(clamp(p, float2(0.5),
        max(u_resolution - 0.5, float2(0.5)))).rgb;
}
float3 hsv(float3 c) {
    float4 K = float4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
    float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    return float3(abs(q.z + (q.w-q.y)/(6.0*d+1e-6)),
        d/(q.x+1e-6), q.x);
}
// Color-only heuristic; this is not face/person segmentation.
float skin(float3 c) {
    float3 h = hsv(max(c, 0.0));
    float hue = smoothstep(0.0, 0.04, h.x)
        * (1.0 - smoothstep(0.13, 0.19, h.x));
    float sat = smoothstep(0.06, 0.18, h.y)
        * (1.0 - smoothstep(0.70, 0.98, h.y));
    return hue * sat * smoothstep(0.04, 0.18, h.z);
}
// Analytic sRGB transfer: host must select an sRGB surface.
float3 linearRGB(float3 c) {
    c = max(c, 0.0);
    return mix(c/12.92, pow((c+0.055)/1.055, float3(2.4)),
        step(float3(0.04045), c));
}
float3 displayRGB(float3 c) {
    c = max(c, 0.0);
    return mix(c*12.92, 1.055*pow(c, float3(1.0/2.4))-0.055,
        step(float3(0.0031308), c));
}
// Hue-preserving shoulder; avoids hard clipping bright channels.
float3 shoulder(float3 c, float knee) {
    c = max(c, 0.0);
    float peak = max(c.r, max(c.g, c.b));
    float target = knee + (1.0-knee)
        * (1.0-exp(-max(peak-knee, 0.0)/(1.0-knee)));
    return c * (peak > knee ? target/max(peak, 1e-5) : 1.0);
}
float hash(float2 p) {
    p = fract(p * float2(123.34, 345.45));
    p += dot(p, p + 34.345);
    return fract(p.x*p.y);
}
float noise(float2 p) {
    float2 i = floor(p), f = fract(p);
    f = f*f*(3.0-2.0*f);
    return mix(mix(hash(i), hash(i+float2(1,0)), f.x),
        mix(hash(i+float2(0,1)), hash(i+float2(1,1)), f.x), f.y);
}
float photoSeed() { return floor(mod(max(u_time, 0.0), 4096.0)); }
float3 grain(float2 p, float size) {
    float2 g = p/shortSide()*1080.0/max(size, 0.5);
    float2 seed = float2(photoSeed()*0.137, photoSeed()*0.071);
    float mono = 2.0*noise(g+seed)-1.0;
    float3 chroma = 2.0*float3(noise(g+seed+11.0),
        noise(g+seed+29.0), noise(g+seed+47.0))-1.0;
    return mix(float3(mono), chroma, 0.10);
}

// Fixed normalization includes dark samples: no bright-only division.
// Radius is in pixels at a 1080-pixel short side; 16 neighbor samples.
float3 brightGlow(float2 p, float radius) {
    float3 sum = float3(0.0);
    float radiusPx = radius * shortSide()/1080.0;
    for (int i=0; i<8; ++i) {
        float angle = float(i)*0.785398163;
        float2 dir = float2(cos(angle), sin(angle));
        for (int j=0; j<2; ++j) {
            float r = j == 0 ? 0.45 : 1.0;
            float3 s = readPhoto(p + dir*radiusPx*r);
            float bright = max(s.r, max(s.g, s.b));
            sum += linearRGB(s)*smoothstep(0.60, 0.94, bright);
        }
    }
    return sum/16.0;
}

const float CONTRAST = 1.24;
const float WARMTH = 0.16;
const float BLOOM_STRENGTH = 0.09;
const float BLOOM_RADIUS = 5.0;
const float CA_OFFSET = 0.4;
const float GRAIN_INTENSITY = 0.025;
const float VIGNETTE_STRENGTH = 0.05;

half4 main(float2 p) {
    float2 uv = p/u_resolution;
    float3 original = readPhoto(p);
    float protect = skin(original);
    float2 radial = (p-u_resolution*0.5)/shortSide();
    float edge = smoothstep(0.12, 0.65, length(radial));
    float2 ca = normalize(radial+float2(1e-5))
        * CA_OFFSET*shortSide()/1080.0*edge;
    float3 c = float3(readPhoto(p+ca).r, original.g, readPhoto(p-ca).b);
    c += float3(0.15, 0.05, -0.10)*WARMTH*(1.0-0.50*protect);
    float y = luma(c);
    float mid = smoothstep(0.2,0.4,y)*(1.0-smoothstep(0.6,0.8,y));
    c *= mix(float3(1), float3(1.08,0.95,0.75),
        mid*0.60*(1.0-0.55*protect));
    c *= mix(float3(1), float3(1.12,1.0,0.88),
        smoothstep(0.6,0.85,y)*0.40*(1.0-0.60*protect));
    c = mix(float3(luma(c)), c, 1.13-0.06*protect);
    c = max((c-0.5)*CONTRAST+0.5, 0.0);
    c = displayRGB(linearRGB(c) + brightGlow(p,BLOOM_RADIUS)
        * BLOOM_STRENGTH*float3(1.0,0.93,0.82));
    c = pow(max(c,0.0), float3(0.94));
    c = shoulder(c,0.82);
    float vig = smoothstep(0.20,0.78,length(radial));
    c *= 1.0 - VIGNETTE_STRENGTH*vig;
    c += grain(p,2.5)*GRAIN_INTENSITY
        * (1.0-0.65*smoothstep(0.60,1.0,luma(c)));
    return half4(clamp(c,0.0,1.0),1.0);
}

