const float EXPOSURE = 1.04;
const float CONTRAST = 0.94;
const float SATURATION = 0.92;
const float PASTEL_STRENGTH = 0.95;
const float SKIN_PROTECT = 0.85;
const float SHADOW_LIFT = 0.10;
const float SHADOW_TINT_STRENGTH = 0.18;
const float3 SHADOW_TINT = float3(0.95,1.02,1.03);

half4 main(float2 p) {
    float3 original = readPhoto(p);
    float protect = skin(original)*SKIN_PROTECT;
    float3 c = displayRGB(linearRGB(original)*EXPOSURE);
    c = max((c-0.5)*CONTRAST+0.5,0.0);
    float3 h = hsv(c);
    float y = luma(c);
    float cool = smoothstep(0.40,0.48,h.x)
        * (1.0-smoothstep(0.66,0.73,h.x));
    float pink = smoothstep(0.76,0.84,h.x)
        * (1.0-smoothstep(0.96,1.0,h.x));
    float palette = max(cool,pink)*(1.0-protect);
    float bright = smoothstep(0.35,0.85,y);
    float sat = SATURATION - 0.16*palette - 0.10*bright*(1.0-protect);
    c = mix(float3(y), c, mix(sat,1.0,protect));
    // Lift selected colors gently, retaining the local tonal structure.
    c = mix(c,float3(0.97,0.97,0.94),0.045*palette);
    float shadow = 1.0-smoothstep(0.05,0.45,luma(c));
    c *= mix(float3(1),SHADOW_TINT,
        shadow*SHADOW_TINT_STRENGTH*(1.0-protect));
    float black = 1.0-smoothstep(0.0,0.25,luma(c));
    c += float3(SHADOW_LIFT*black*0.5);
    c = shoulder(c,0.78);
    c = mix(original,c,clamp(PASTEL_STRENGTH,0.0,1.0));
    float2 radial = (p-u_resolution*0.5)/shortSide();
    c *= 1.0-0.035*smoothstep(0.25,0.80,length(radial));
    c += grain(p,1.8)*0.008
        * (1.0-0.70*smoothstep(0.60,1.0,luma(c)));
    return half4(clamp(c,0.0,1.0),1.0);
}

