const float FLASH_INTENSITY = 0.34;
const float FLASH_RADIUS = 0.72;
const float FLASH_FALLOFF = 1.35;
const float2 FLASH_CENTER = float2(0.5,0.4);
const float CONTRAST = 1.16;
const float SATURATION = 1.10;
const float BACKGROUND_DESAT = 0.32;
const float HIGHLIGHT_BOOST = 0.10;
const float MINI_HALATION = 0.08;

half4 main(float2 p) {
    float3 original = readPhoto(p);
    float protect = skin(original);
    // Short-side metric makes the hotspot circular at any aspect ratio.
    float d = length((p-FLASH_CENTER*u_resolution)/shortSide());
    float radial = pow(max(d/FLASH_RADIUS,0.0),FLASH_FALLOFF);
    float flash = 1.0-smoothstep(0.0,1.0,radial);
    float gain = mix(0.68,1.0+FLASH_INTENSITY,flash);
    float3 c = displayRGB(linearRGB(original)*gain);
    c = max((c-0.45)*CONTRAST+0.45,0.0);
    float cool = 0.45*(1.0-0.85*protect);
    c *= mix(float3(1),float3(0.96,1.015,1.045),cool);
    float shadow = 1.0-smoothstep(0.04,0.24,luma(c));
    float bg = clamp(0.55*shadow+0.55*(1.0-flash),0.0,1.0);
    c = mix(c,float3(luma(c)),bg*BACKGROUND_DESAT*(1.0-0.7*protect));
    c = max(mix(float3(luma(c)),c,
        1.0+(SATURATION-1.0)*(1.0-0.80*protect)),0.0);
    float highlight = smoothstep(0.65,0.94,luma(c));
    float3 lit = linearRGB(c)*(1.0+HIGHLIGHT_BOOST*highlight*flash);
    lit += brightGlow(p,3.0)*MINI_HALATION*float3(1.0,0.80,0.62)
        * (1.0-0.70*protect);
    c = shoulder(displayRGB(lit),0.80);
    c += grain(p,1.9)*0.014
        * (1.0-0.75*smoothstep(0.65,1.0,luma(c)));
    return half4(clamp(c,0.0,1.0),1.0);
}

// FilmCam36 / Instella / v2.1
// Nashville-inspired: indigo shadows, peach midtones and cream highlights.
// Tuned against the supplied visual reference, not Instagram's proprietary LUT.
// Artistic profile, not a measured film-stock or camera simulation.
// Skia RuntimeEffect (SkSL), display-referred SDR sRGB working surface.
// u_image must cover exactly u_resolution in local pixel coordinates.
// Keep u_time FIXED per photograph: it is a persisted texture seed, not a clock.
// Full-frame color treatment only; framing and capture behavior belong to the UI.
uniform shader u_image;
uniform float2 u_resolution;
uniform float u_time;

const float GRAIN_AMOUNT = 0.002;
const float SOFTNESS = 0.025;

float2 imageSize() { return max(u_resolution, float2(1.0)); }

float4 readImage(float2 p) {
    float4 s = float4(u_image.eval(clamp(p, float2(0.5), imageSize() - 0.5)));
    // Skia child shaders return premultiplied color.
    return float4(s.rgb / max(s.a, 0.00001), s.a);
}

float hash21(float2 p, float seed) {
    float3 q = fract(float3(p.x, p.y, p.x + p.y) *
                     float3(0.1031, 0.11369, 0.13787) + seed * 0.017);
    q += dot(q, q.yzx + 19.19);
    return fract((q.x + q.y) * q.z);
}

float noise2(float2 p, float seed) {
    float2 cell = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(cell, seed), hash21(cell + float2(1.0, 0.0), seed), f.x),
               mix(hash21(cell + float2(0.0, 1.0), seed),
                   hash21(cell + float2(1.0, 1.0), seed), f.x), f.y);
}

float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }

// Smooth display-space color response fitted to the aligned reference photo.
// Cubic channel curves plus cross-channel terms capture the blue toe, cyan
// sky and restrained peach skin without applying one tint to every midtone.
// This is a screenshot-based approximation, not Instagram's original LUT.
float3 nashvilleColor(float3 c) {
    c = clamp(c, 0.0, 1.0);
    float3 c2 = c * c;
    float3 c3 = c2 * c;
    return float3(-0.0341668, -0.0242863, 0.1249458) * 1.0
         + float3(1.0220804, 0.0379557, -0.0211805) * c.r
         + float3(-0.1349958, 1.2077106, -0.0044899) * c.g
         + float3(0.0087450, -0.0311187, 0.8371986) * c.b
         + float3(0.5731357, -0.0252543, 0.0236234) * c2.r
         + float3(0.3315596, -0.1429448, 0.0356635) * c2.g
         + float3(-0.0197884, -0.0089044, -0.0261632) * c2.b
         + float3(-0.5544369, 0.0145146, 0.0023498) * c3.r
         + float3(-0.2591795, -0.1276109, -0.0489312) * c3.g
         + float3(0.0394626, 0.0518776, -0.0174168) * c3.b;
}

half4 main(float2 frag_coord) {
    float4 src = readImage(frag_coord);
    if (src.a <= 0.00001) { return half4(0.0); }
    float2 size = imageSize();
    float scale = max(min(size.x, size.y) / 1080.0, 0.25);
    float seed = mod(floor(u_time), 4096.0);
    float3 c = clamp(src.rgb, 0.0, 1.0);
    float y = luma(c);
    float fine = noise2(frag_coord / scale / 1.2, seed) - 0.5;
    float coarse = noise2(frag_coord / scale / 3.3 + 31.7, seed + 97.0) - 0.5;
    float envelope = 0.3 + 0.7 * pow(max(4.0 * y * (1.0 - y), 0.0), 0.7);
    float grain = (fine * 0.8 + coarse * 0.2) * envelope;

    // Short-range lens softness, alpha-weighted to avoid transparent fringes.
    float radius = 1.7 * scale;
    float4 a = readImage(frag_coord + float2(radius, 0.0));
    float4 b = readImage(frag_coord - float2(radius, 0.0));
    float4 d = readImage(frag_coord + float2(0.0, radius));
    float4 e = readImage(frag_coord - float2(0.0, radius));
    float3 soft = (a.rgb*a.a + b.rgb*b.a + d.rgb*d.a + e.rgb*e.a) /
                  max(a.a + b.a + d.a + e.a, 0.00001);
    c = mix(c, soft, SOFTNESS);
    c = nashvilleColor(c);
    c += float3(grain * GRAIN_AMOUNT * 2.0);
    c = clamp(c, 0.0, 1.0);
    // Restore premultiplication and preserve the source alpha.
    return half4(c * src.a, src.a);
}

// FilmCam36 — Lomocore R3
// Opaque SDR / sRGB; source-image pixel coordinates.
// u_time: different integer seed [0,4095] for each new photo.
// Save and reuse the seed for preview/export. Do not animate it.
uniform shader u_image;
uniform float2 u_resolution;
uniform float u_time;

const float EXPOSURE = 1.08;
const float CONTRAST = 1.38;
const float SATURATION = 1.55;
const float BARREL_DISTORTION = 0.06;
const float SOFT_FOCUS = 0.45;
const float CROSS_PROCESS = 0.80;
const float VIGNETTE_STRENGTH = 0.38;
const float GRAIN_INTENSITY = 0.027;
const float BURN_INTENSITY_BASE = 3.60;
const float BURN_WIDTH_BASE = 0.22;
const float BURN_SOFTNESS_BASE = 0.48;
const float BURN_SPREAD = 0.20;
const float BURN_SKIN_PROTECT = 0.35;
const float BURN_GLOW = 0.14;

float luma(float3 c) {
    return dot(c,float3(0.2126,0.7152,0.0722));
}
float shortSide() {
    return max(min(u_resolution.x,u_resolution.y),1.0);
}
float3 readPhoto(float2 p) {
    return clamp(float3(u_image.eval(clamp(p,float2(0.5),
        max(u_resolution-0.5,float2(0.5)))).rgb),0.0,1.0);
}
float hash(float2 p) {
    p = fract(p*float2(123.34,345.45));
    p += dot(p,p+34.345);
    return fract(p.x*p.y);
}
float noise(float2 p) {
    float2 i = floor(p), f = fract(p);
    f = f*f*(3.0-2.0*f);
    return mix(mix(hash(i),hash(i+float2(1,0)),f.x),
        mix(hash(i+float2(0,1)),hash(i+float2(1,1)),f.x),f.y);
}
float photoSeed() {
    return floor(mod(max(u_time,0.0),4096.0));
}
float3 hsv(float3 c) {
    float4 K = float4(0.0,-1.0/3.0,2.0/3.0,-1.0);
    float4 p = mix(float4(c.bg,K.wz),float4(c.gb,K.xy),step(c.b,c.g));
    float4 q = mix(float4(p.xyw,c.r),float4(c.r,p.yzx),step(p.x,c.r));
    float d = q.x-min(q.w,q.y);
    return float3(abs(q.z+(q.w-q.y)/(6.0*d+0.00001)),
        d/(q.x+0.00001),q.x);
}
float skin(float3 c) {
    float3 h = hsv(clamp(c,0.0,1.0));
    return smoothstep(0.0,0.04,h.x)*(1.0-smoothstep(0.13,0.19,h.x))
        * smoothstep(0.06,0.18,h.y)*(1.0-smoothstep(0.70,0.98,h.y))
        * smoothstep(0.04,0.18,h.z);
}
float3 linearRGB(float3 c) {
    c = max(c,0.0);
    return mix(c/12.92,pow((c+0.055)/1.055,float3(2.4)),
        step(float3(0.04045),c));
}
float3 displayRGB(float3 c) {
    c = max(c,0.0);
    return mix(c*12.92,1.055*pow(c,float3(1.0/2.4))-0.055,
        step(float3(0.0031308),c));
}
float3 shoulder(float3 c,float knee) {
    c = max(c,0.0);
    float peak = max(c.r,max(c.g,c.b));
    float target = knee+(1.0-knee)
        * (1.0-exp(-max(peak-knee,0.0)/(1.0-knee)));
    return c*(peak>knee ? target/max(peak,1e-5) : 1.0);
}
float3 grain(float2 p,float size) {
    float2 g = p/shortSide()*1080.0/max(size,0.1);
    g += float2(0.137,0.071)*photoSeed();
    float mono = noise(g)-0.5;
    float3 colored = float3(noise(g+float2(11,17)),
        noise(g+float2(29,31)),noise(g+float2(47,53)))-0.5;
    return mix(float3(mono),colored,0.10);
}

half4 main(float2 p) {
    float2 resolution = max(u_resolution,float2(1.0));
    float2 uv = clamp(p/resolution,0.0,1.0);
    float2 centered = uv*2.0-1.0;
    float radius = length(centered);
    float k = clamp(BARREL_DISTORTION,0.0,0.30);
    float2 lens = centered*(1.0+k*dot(centered,centered))/(1.0+2.0*k);
    float2 sampleP = (lens*0.5+0.5)*resolution;
    float3 original = readPhoto(sampleP);
    float px = 1.5*shortSide()/1080.0;
    float3 blur = (readPhoto(sampleP+float2(-px,-px))
        + readPhoto(sampleP+float2(px,-px))
        + readPhoto(sampleP+float2(-px,px))
        + readPhoto(sampleP+float2(px,px)))*0.25;
    float3 c = mix(original,blur,
        smoothstep(0.20,1.20,radius)*clamp(SOFT_FOCUS,0.0,1.0));
    float protect = skin(original);
    c = displayRGB(linearRGB(c)*EXPOSURE);
    c = max((c-0.5)*CONTRAST+0.5,0.0);
    float brightness = luma(c);
    float shadow = 1.0-smoothstep(0.0,0.50,brightness);
    float high = smoothstep(0.50,1.0,brightness);
    c *= mix(float3(1),float3(0.88,1.15,1.12),
        clamp(shadow*0.75*CROSS_PROCESS*(1.0-0.35*protect),0.0,1.0));
    c *= mix(float3(1),float3(1.15,1.08,0.88),
        clamp(high*0.60*CROSS_PROCESS*(1.0-0.45*protect),0.0,1.0));
    c = pow(max(c,0.0),float3(0.90));
    c = max(mix(float3(luma(c)),c,max(SATURATION-0.20*protect,0.0)),0.0);
    c = shoulder(c,0.82);

    // Apply vignette BEFORE the burn.
    c *= 1.0-clamp(VIGNETTE_STRENGTH,0.0,1.0)*smoothstep(0.30,1.35,radius);
    float photoId = photoSeed();
    float seed = hash(float2(photoId+17.13,photoId*0.731+43.71))*251.0;
    float edge = floor(hash(float2(seed+11.7,seed+83.2))*4.0);
    float anchor = mix(0.12,0.88,hash(float2(seed+37.4,seed+19.8)));
    float2 q;
    if (edge<1.0) q = float2(uv.x,abs(uv.y-anchor));
    else if (edge<2.0) q = float2(1.0-uv.x,abs(uv.y-anchor));
    else if (edge<3.0) q = float2(uv.y,abs(uv.x-anchor));
    else q = float2(1.0-uv.y,abs(uv.x-anchor));

    float width = clamp(BURN_WIDTH_BASE*mix(0.82,1.18,
        hash(float2(seed,3.456))),0.04,0.85);
    float burnLength = mix(0.28,0.46,hash(float2(seed,4.567)));
    float intensity = max(BURN_INTENSITY_BASE,0.0)
        * mix(0.85,1.20,hash(float2(seed,5.678)));
    float softness = clamp(BURN_SOFTNESS_BASE,0.0,1.0);
    float phase = hash(float2(seed,6.789))*6.283185;
    float wave = sin(q.y*8.0+phase)*width*0.10;
    wave += (noise(float2(q.y*4.0,seed+7.1))-0.5)*width*0.20;
    float widthAtY = max(width*(1.0+q.y*BURN_SPREAD)+wave,0.02);
    float lengthMask = pow(1.0-smoothstep(0.0,burnLength,q.y),1.05);
    float sideMask = pow(1.0-smoothstep(0.0,widthAtY,q.x),
        mix(3.6,1.15,softness));
    float broadMask = pow(1.0-smoothstep(0.0,widthAtY*1.15,q.x),1.65)*lengthMask;
    float cloud1 = noise(q*float2(3.5,5.5)+float2(seed,seed+12.3));
    float cloud2 = noise(q*float2(8.0,11.0)+float2(seed+21.7,seed));
    float cloud = mix(0.72,1.0,cloud1*0.70+cloud2*0.30);
    float skinProtection = 1.0-clamp(BURN_SKIN_PROTECT,0.0,1.0)*protect;
    float burnMask = clamp(sideMask*lengthMask*cloud*skinProtection,0.0,1.0);
    broadMask *= cloud*skinProtection;

    float3 burnColor = mix(float3(0.95,0.055,0.012),float3(1.0,0.38,0.045),
        smoothstep(0.04,0.30,burnMask));
    burnColor = mix(burnColor,float3(1.0,0.78,0.24),smoothstep(0.25,0.62,burnMask));
    burnColor = mix(burnColor,float3(1.0,0.97,0.88),smoothstep(0.55,0.88,burnMask));
    float glowOpacity = 1.0-exp(-max(BURN_GLOW,0.0)*intensity*max(broadMask,0.0));
    c = 1.0-(1.0-c)*(1.0-float3(0.95,0.10,0.025)*glowOpacity);
    float burnOpacity = 1.0-exp(-intensity*burnMask*1.20);
    c = 1.0-(1.0-c)*(1.0-burnColor*burnOpacity);
    float core = smoothstep(0.52,0.90,burnMask);
    c = mix(c,float3(1.0,0.98,0.91),core*(1.0-exp(-intensity))*0.45);
    float grainMask = (1.0-0.65*smoothstep(0.65,1.0,luma(c)))*(1.0-0.45*burnOpacity);
    c += grain(p,2.5)*GRAIN_INTENSITY*grainMask;
    return half4(clamp(c,0.0,1.0),1.0);
}

// FilmCam36 / Metrochrome / v1.1
// Restrained documentary palette: olive greens, brick reds, cool shadows.
// Artistic profile, not a measured film-stock or camera simulation.
// Skia RuntimeEffect (SkSL), display-referred SDR sRGB working surface.
// u_image must cover exactly u_resolution in local pixel coordinates.
// Keep u_time FIXED per photograph: it is a persisted texture seed, not a clock.
// Full-frame color treatment only; framing and capture behavior belong to the UI.
uniform shader u_image;
uniform float2 u_resolution;
uniform float u_time;

const float SATURATION = 0.54;
const float CONTRAST = 1.23;
const float GRAIN_AMOUNT = 0.036;

float2 imageSize() { return max(u_resolution, float2(1.0)); }

float4 readImage(float2 p) {
    float4 s = float4(u_image.eval(clamp(p, float2(0.5), imageSize() - 0.5)));
    // Skia child shaders return premultiplied color.
    return float4(s.rgb / max(s.a, 0.00001), s.a);
}

float hash21(float2 p, float seed) {
    float3 q = fract(float3(p.x, p.y, p.x + p.y) *
                     float3(0.1031, 0.11369, 0.13787) + seed * 0.017);
    q += dot(q, q.yzx + 19.19);
    return fract((q.x + q.y) * q.z);
}

float noise2(float2 p, float seed) {
    float2 cell = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(cell, seed), hash21(cell + float2(1.0, 0.0), seed), f.x),
               mix(hash21(cell + float2(0.0, 1.0), seed),
                   hash21(cell + float2(1.0, 1.0), seed), f.x), f.y);
}

float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }

float3 toneCurve(float3 c, float contrast) {
    c = clamp(c, 0.0, 1.0);
    float3 a = pow(max(c, float3(0.00001)), float3(contrast));
    float3 b = pow(max(1.0 - c, float3(0.00001)), float3(contrast));
    return a / (a + b);
}


half4 main(float2 frag_coord) {
    float4 src = readImage(frag_coord);
    if (src.a <= 0.00001) { return half4(0.0); }
    float2 size = imageSize();
    float scale = max(min(size.x, size.y) / 1080.0, 0.25);
    float seed = mod(floor(u_time), 4096.0);
    float3 c = clamp(src.rgb, 0.0, 1.0);
    float y = luma(c);
    float edge = smoothstep(0.26, 0.72, length(frag_coord / size - 0.5));
    float fine = noise2(frag_coord / scale / 1.2, seed) - 0.5;
    float coarse = noise2(frag_coord / scale / 3.3 + 31.7, seed + 97.0) - 0.5;
    float envelope = 0.3 + 0.7 * pow(max(4.0 * y * (1.0 - y), 0.0), 0.7);
    float grain = (fine * 0.8 + coarse * 0.2) * envelope;

    float warm = smoothstep(0.02, 0.16, c.r - c.b) *
                 smoothstep(-0.01, 0.10, c.r - c.g);
    float green = smoothstep(0.01, 0.15, c.g - max(c.r, c.b));
    c = mix(float3(y), c, mix(SATURATION, 0.78, warm));
    c += float3(0.022, -0.012, -0.045) * green;
    float shadow = 1.0 - smoothstep(0.08, 0.48, y);
    c += float3(-0.027, 0.012, 0.024) * shadow * (1.0 - warm * 0.8);
    c = toneCurve(c * 0.90, CONTRAST);
    c = mix(float3(0.027, 0.043, 0.049), float3(0.910, 0.925, 0.903), c);
    c += float3(grain * GRAIN_AMOUNT * 2.0);
    c *= 1.0 - 0.12 * edge;
    c = clamp(c, 0.0, 1.0);
    // Restore premultiplication and preserve the source alpha.
    return half4(c * src.a, src.a);
}

// FilmCam36 / Digi '04 / v2.0
// Early compact-digital-inspired ISP, not a calibrated camera profile.
// SkSL RuntimeEffect. SDR sRGB working surface, premultiplied input/output.
// u_image and u_resolution must use the same source-image pixel coordinates.
// u_time: saved integer photo seed [0,4095]. Reuse for preview/export.
uniform shader u_image;
uniform float2 u_resolution;
uniform float u_time;

const float LOOK_STRENGTH = 1.0;
const float EXPOSURE = 1.025;
const float CONTRAST = 1.27;
const float BLACK_POINT = 0.012;
const float WHITE_POINT = 0.965;
const float SATURATION = 1.24;
const float SHARPNESS = 0.68;
const float DETAIL_SOFTENING = 0.24;
const float CHROMA_SMOOTHING = 0.22;
const float LUMA_NOISE = 0.014;
const float CHROMA_NOISE = 0.009;
const float VIGNETTE = 0.035;

float2 imageSize() { return max(u_resolution,float2(1.0)); }
float shortSide() { return max(min(u_resolution.x,u_resolution.y),1.0); }
float luma(float3 c) { return dot(c,float3(0.2126,0.7152,0.0722)); }

float4 readImage(float2 p) {
    float4 s = float4(u_image.eval(clamp(p,float2(0.5),imageSize()-0.5)));
    return float4(clamp(s.rgb/max(s.a,0.00001),0.0,1.0),s.a);
}
float hash21(float2 p,float seed) {
    float3 q = fract(float3(p.x,p.y,p.x+p.y)
        * float3(0.1031,0.11369,0.13787)+seed*0.017);
    q += dot(q,q.yzx+19.19);
    return fract((q.x+q.y)*q.z);
}
float noise2(float2 p,float seed) {
    float2 i = floor(p), f = fract(p);
    f = f*f*(3.0-2.0*f);
    return mix(mix(hash21(i,seed),hash21(i+float2(1,0),seed),f.x),
        mix(hash21(i+float2(0,1),seed),hash21(i+float2(1,1),seed),f.x),f.y);
}
float3 toHSV(float3 c) {
    float4 K = float4(0.0,-1.0/3.0,2.0/3.0,-1.0);
    float4 p = mix(float4(c.bg,K.wz),float4(c.gb,K.xy),step(c.b,c.g));
    float4 q = mix(float4(p.xyw,c.r),float4(c.r,p.yzx),step(p.x,c.r));
    float d = q.x-min(q.w,q.y);
    return float3(abs(q.z+(q.w-q.y)/(6.0*d+1e-6)),d/(q.x+1e-6),q.x);
}
float band(float x,float a,float b,float c,float d) {
    return smoothstep(a,b,x)*(1.0-smoothstep(c,d,x));
}
// Color heuristic, not face segmentation.
float skinMask(float3 h) {
    return band(h.x,0.0,0.035,0.13,0.19)
        * band(h.y,0.05,0.18,0.72,0.96)*smoothstep(0.06,0.20,h.z);
}
float toneCurve(float v) {
    float x = clamp((v-BLACK_POINT)/(WHITE_POINT-BLACK_POINT),0.0,1.0);
    float a = pow(x,CONTRAST);
    float b = pow(1.0-x,CONTRAST);
    return a/max(a+b,0.00001);
}

half4 main(float2 p) {
    float4 src = readImage(p);
    if (src.a<=0.00001) return half4(0.0);
    if (LOOK_STRENGTH<=0.0) return half4(src.rgb*src.a,src.a);
    float3 original = src.rgb;
    float y = luma(original);
    float3 h = toHSV(original);
    float skin = skinMask(h);
    float r = 0.90*shortSide()/1080.0;

    // Nine-tap optical/detail response; alpha-aware at cutout edges.
    float3 sum = original*src.a*4.0;
    float weightSum = src.a*4.0;
    float low = y, high = y;
    for (int j=-1;j<=1;++j) {
        for (int i=-1;i<=1;++i) {
            if (i==0 && j==0) continue;
            float4 s = readImage(p+float2(float(i),float(j))*r);
            float w = (i==0 || j==0) ? 2.0 : 1.0;
            sum += s.rgb*s.a*w;
            weightSum += s.a*w;
            float sy = mix(y,luma(s.rgb),s.a);
            low = min(low,sy);
            high = max(high,sy);
        }
    }
    float3 blur = sum/max(weightSum,0.00001);
    float flatness = 1.0-smoothstep(0.012,0.075,high-low);
    float3 c = mix(original,blur,DETAIL_SOFTENING*(0.35+0.65*flatness));

    // Smooth color detail more than brightness detail.
    float cy = luma(c);
    float3 softChroma = blur-float3(luma(blur));
    c = float3(cy)+mix(c-float3(cy),softChroma,CHROMA_SMOOTHING);

    // Small luminance edge overshoot, with a noise threshold and hard limit.
    float detail = y-luma(blur);
    float edge = smoothstep(0.003,0.025,abs(detail));
    float sharpen = clamp(detail*SHARPNESS*edge,-0.035,0.035);
    c = max(c+float3(sharpen),0.0);

    // Neutral-preserving color matrix: stronger primary-color separation.
    float3 mapped = float3(
        dot(c,float3(1.075,-0.045,-0.030)),
        dot(c,float3(-0.025,1.055,-0.030)),
        dot(c,float3(-0.035,-0.025,1.060))
    );
    c = mix(c,mapped,1.0-0.85*skin);
    float saturation = mix(SATURATION,1.025,skin);
    c = max(mix(float3(luma(c)),c,saturation),0.0);

    // Blue/cyan separation without a global blue overlay.
    float blue = band(h.x,0.46,0.53,0.68,0.74)*smoothstep(0.12,0.55,h.y);
    c += float3(-0.012,0.018,0.012)*blue*(1.0-0.75*skin);
    float shadow = (1.0-smoothstep(0.08,0.48,y))*smoothstep(0.015,0.10,y);
    c += float3(-0.006,0.002,0.010)*shadow*(1.0-0.80*skin);

    // Shorter highlight transition and deeper shadows than the old version.
    // This is a display-referred rendering curve, not recovered RAW exposure.
    c = max(c*EXPOSURE,0.0);
    float inputY = luma(c);
    float3 channelTone = float3(toneCurve(c.r),toneCurve(c.g),toneCurve(c.b));
    float3 luminanceTone = c*(toneCurve(inputY)/max(inputY,0.00001));
    c = mix(channelTone,luminanceTone,0.90*skin);
    float white = smoothstep(0.82,0.98,y)*(1.0-smoothstep(0.06,0.22,h.y));
    c = mix(c,float3(luma(c)),white*0.80);

    float2 uv = p/imageSize();
    c *= 1.0-VIGNETTE*smoothstep(0.35,0.71,length(uv-0.5));

    // Fine digital noise. Dark regions get more chroma variation.
    // Stylized texture, not an ISO estimate or a CCD sensor simulation.
    float seed = floor(mod(max(u_time,0.0),4096.0));
    float2 grid = p/shortSide()*1440.0;
    float2 cell = floor(grid);
    float n = hash21(cell,seed)+hash21(cell+float2(71,19),seed+37.0)-1.0;
    float3 cn = float3(noise2(grid/2.8+17.0,seed+31.0),
        noise2(grid/2.8+47.0,seed+71.0),
        noise2(grid/2.8+83.0,seed+113.0))*2.0-1.0;
    cn -= float3(luma(cn));
    float dark = 1.0-smoothstep(0.10,0.65,y);
    float visible = smoothstep(0.003,0.035,luma(c))
        * (1.0-smoothstep(0.88,1.0,luma(c)));
    c += (float3(n)*LUMA_NOISE*(0.22+0.78*dark)
        + cn*CHROMA_NOISE*dark)*visible;

    // Normal 8-bit output rounding, NOT simulated JPEG/DCT compression.
    c = floor(clamp(c,0.0,1.0)*255.0+0.5)/255.0;
    c = mix(original,c,clamp(LOOK_STRENGTH,0.0,1.0));
    return half4(c*src.a,src.a);
}

// FilmCam36 / Silver 400 / v1.0
// Skia RuntimeEffect (SkSL), display-referred SDR sRGB working surface.
// u_image must cover exactly u_resolution in local pixel coordinates.
// Keep u_time FIXED per photograph: it is a persisted grain seed, not a clock.
uniform shader u_image;
uniform float2 u_resolution;
uniform float u_time;

const float CONTRAST = 1.26;
const float BLACK_FLOOR = 0.009;
const float WHITE_CEILING = 0.987;
const float GRAIN_AMOUNT = 0.037;
const float GLOW_AMOUNT = 0.045;
const float VIGNETTE_AMOUNT = 0.085;

float2 imageSize() { return max(u_resolution, float2(1.0)); }

float4 readImage(float2 p) {
    float4 s = float4(u_image.eval(clamp(p, float2(0.5), imageSize() - 0.5)));
    // Skia child shaders return premultiplied color.
    return float4(s.rgb / max(s.a, 0.00001), s.a);
}

float mono(float3 c) {
    // A mild yellow-filter-like response: luminous warm skin, deeper blue sky.
    // This is an artistic film profile, not a measured film-stock simulation.
    return dot(clamp(c, 0.0, 1.0), float3(0.34, 0.58, 0.08));
}

float hash21(float2 p, float seed) {
    float3 q = fract(float3(p.x, p.y, p.x + p.y) *
                     float3(0.1031, 0.11369, 0.13787) + seed * 0.017);
    q += dot(q, q.yzx + 19.19);
    return fract((q.x + q.y) * q.z);
}

float noise2(float2 p, float seed) {
    float2 cell = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(cell, seed), hash21(cell + float2(1.0, 0.0), seed), f.x),
               mix(hash21(cell + float2(0.0, 1.0), seed),
                   hash21(cell + float2(1.0, 1.0), seed), f.x), f.y);
}

float densityCurve(float x) {
    x = clamp(x, 0.0, 1.0);
    float a = pow(max(x, 0.00001), CONTRAST);
    float b = pow(max(1.0 - x, 0.00001), CONTRAST);
    return mix(BLACK_FLOOR, WHITE_CEILING, a / (a + b));
}

float highlight(float2 p) {
    float4 s = readImage(p);
    float y = mono(s.rgb);
    return y * smoothstep(0.72, 0.98, y) * s.a;
}

half4 main(float2 frag_coord) {
    float4 src = readImage(frag_coord);
    if (src.a <= 0.00001) { return half4(0.0); }
    float2 size = imageSize();
    float scale = max(min(size.x, size.y) / 1080.0, 0.25);
    float y = densityCurve(mono(src.rgb) * 1.025);

    // Four local highlight taps. Coordinates and radius are BOTH in pixels.
    // Modest diffusion only; not a physical multi-pass bloom/halation model.
    float radius = 2.2 * scale;
    float glow = (highlight(frag_coord + float2(radius, 0.0)) +
                  highlight(frag_coord - float2(radius, 0.0)) +
                  highlight(frag_coord + float2(0.0, radius)) +
                  highlight(frag_coord - float2(0.0, radius))) * 0.25;
    y += GLOW_AMOUNT * glow * (1.0 - y);

    float2 uv = frag_coord / size;
    float edge = smoothstep(0.24, 0.72, length(uv - 0.5));
    y *= 1.0 - VIGNETTE_AMOUNT * edge;

    // Two-scale monochrome grain, stable relative to a 1080px short edge.
    float seed = mod(floor(u_time), 4096.0);
    float2 p = frag_coord / scale;
    float fine = noise2(p / 1.15, seed) - 0.5;
    float coarse = noise2(p / 3.1 + 31.7, seed + 97.0) - 0.5;
    float envelope = 0.25 + 0.75 * pow(max(4.0 * y * (1.0 - y), 0.0), 0.7);
    y += (fine * 0.80 + coarse * 0.20) * 2.0 * GRAIN_AMOUNT * envelope;
    y = clamp(y, 0.0, 1.0);
    // Equal R/G/B by design; preserve the original alpha.
    return half4(float3(y) * src.a, src.a);
}

// FilmCam36 — Nightchrome R3
// Opaque SDR / sRGB; source-image pixel coordinates.
// u_time: saved integer photo seed [0,4095], not a clock.
// No diagnostic overlay. LOOK_STRENGTH controls the real effect.
uniform shader u_image;
uniform float2 u_resolution;
uniform float u_time;

const float LOOK_STRENGTH = 1.0;
const float EXPOSURE = 1.02;
const float CONTRAST = 1.34;
const float SATURATION = 1.28;
const float CYAN_SHADOWS = 1.0;
const float NEON_BOOST = 0.32;
const float HALATION = 0.55;
const float HALO_RADIUS = 14.0;
const float VIGNETTE = 0.22;
const float GRAIN = 0.014;

float lum(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
float shortSide() {
    return max(min(u_resolution.x, u_resolution.y), 1.0);
}
float3 samplePhoto(float2 p) {
    return clamp(float3(u_image.eval(clamp(p, float2(0.5),
        max(u_resolution - 0.5, float2(0.5)))).rgb), 0.0, 1.0);
}
float3 toHSV(float3 c) {
    float4 K = float4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
    float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    return float3(abs(q.z + (q.w-q.y)/(6.0*d+1e-6)),
        d/(q.x+1e-6), q.x);
}
float hueBand(float h, float a, float b, float c, float d) {
    return smoothstep(a,b,h) * (1.0-smoothstep(c,d,h));
}
float skinMask(float3 h) {
    return hueBand(h.x,0.0,0.04,0.13,0.19)
        * smoothstep(0.06,0.18,h.y)
        * (1.0-smoothstep(0.75,0.98,h.y))
        * smoothstep(0.03,0.18,h.z);
}
float3 compressHighlights(float3 c) {
    c = max(c,0.0);
    float peak = max(c.r,max(c.g,c.b));
    float knee = 0.84;
    float target = knee + (1.0-knee)
        * (1.0-exp(-max(peak-knee,0.0)/(1.0-knee)));
    return c * (peak > knee ? target/max(peak,1e-5) : 1.0);
}
float hash(float2 p) {
    p = fract(p*float2(123.34,345.45));
    p += dot(p,p+34.345);
    return fract(p.x*p.y);
}
float noise(float2 p) {
    float2 i = floor(p), f = fract(p);
    f = f*f*(3.0-2.0*f);
    return mix(mix(hash(i),hash(i+float2(1,0)),f.x),
        mix(hash(i+float2(0,1)),hash(i+float2(1,1)),f.x),f.y);
}
float brightPass(float3 c) {
    return smoothstep(0.55,0.92,max(c.r,max(c.g,c.b)));
}
// Display-space glow; 25 samples, fixed per pixel.
float3 haloBlur(float2 p) {
    float stepPx = HALO_RADIUS*shortSide()/1080.0*0.5;
    float3 sum = float3(0.0);
    float total = 0.0;
    for (int y=-2; y<=2; ++y) {
        for (int x=-2; x<=2; ++x) {
            float2 q = float2(float(x),float(y));
            float weight = exp(-dot(q,q)*0.40);
            float3 s = samplePhoto(p+q*stepPx);
            sum += s*brightPass(s)*weight;
            total += weight;
        }
    }
    return sum/max(total,1e-5);
}

half4 main(float2 p) {
    float3 original = samplePhoto(p);
    if (LOOK_STRENGTH <= 0.0) return half4(original,1.0);
    float y = lum(original);
    float3 h = toHSV(original);
    float skin = skinMask(h);

    // Luminance contrast preserves hue and shadow detail.
    float exposed = clamp(pow(max(y,0.0),0.94)*EXPOSURE,0.0,1.0);
    float sCurve = exposed*exposed*(3.0-2.0*exposed);
    float tone = mix(exposed,sCurve,clamp((CONTRAST-1.0)*2.0,0.0,1.0));
    float3 c = original * (tone/max(y,1e-5));

    // Strong cool shadows, tapering to zero at pure black.
    float shadow = (1.0-smoothstep(0.12,0.66,y))
        * smoothstep(0.015,0.14,y);
    c += float3(-0.075,0.026,0.095)
        * shadow*CYAN_SHADOWS*(1.0-0.70*skin);

    // Cool midtones make the look visible beyond neon scenes.
    float mid = smoothstep(0.14,0.35,y)*(1.0-smoothstep(0.55,0.82,y));
    c += float3(-0.025,0.012,0.030)*mid*(1.0-0.75*skin);

    // Warm highlights; protect near-white areas from a global cast.
    float high = smoothstep(0.48,0.82,y)*(1.0-smoothstep(0.90,1.0,y));
    c += float3(0.040,0.006,-0.035)*high*(1.0-0.65*skin);
    c = max(c,0.0);

    float cyan = hueBand(h.x,0.36,0.43,0.61,0.68)*smoothstep(0.12,0.50,h.y);
    float pink = hueBand(h.x,0.72,0.79,0.93,0.99)*smoothstep(0.12,0.50,h.y);
    c *= mix(float3(1.0),float3(0.82,1.08,1.18),cyan);
    c *= mix(float3(1.0),float3(1.15,0.88,1.08),pink);
    float saturation = 1.0 + (SATURATION-1.0
        + NEON_BOOST*max(cyan,pink))*(1.0-0.70*skin);
    c = max(mix(float3(lum(c)),c,saturation),0.0);

    // Only positive local spill: uniform bright areas do not glow.
    float3 halo = max(haloBlur(p)-original*brightPass(original),0.0);
    float haloMask = (1.0-0.70*smoothstep(0.55,0.95,y))*(1.0-0.60*skin);
    c += halo*float3(1.0,0.24,0.10)*HALATION*haloMask;
    c = compressHighlights(c);

    float2 radial = (p-u_resolution*0.5)/shortSide();
    c *= 1.0-VIGNETTE*smoothstep(0.25,0.85,length(radial));
    float seed = floor(mod(max(u_time,0.0),4096.0));
    float2 grainP = p/shortSide()*1080.0/2.2 + float2(seed*0.137,seed*0.071);
    float grain = noise(grainP)*2.0-1.0;
    float grainMask = smoothstep(0.01,0.08,lum(c))
        * (1.0-0.65*smoothstep(0.60,1.0,lum(c)));
    c += float3(grain*GRAIN*grainMask);
    c = mix(original,clamp(c,0.0,1.0),clamp(LOOK_STRENGTH,0.0,1.0));
    return half4(c,1.0);
}

// Uniforms
uniform shader u_image;
uniform float2 u_resolution;
uniform float u_time;

// Main shader function - simply returns the original image
half4 main(float2 frag_coord) {
    return u_image.eval(frag_coord);
}
